package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.test.util.ReflectionTestUtils;
import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static com.storemate.backend.web.StatutoryPayCalculator.*;

@SpringBootTest @Transactional class StatutoryPayrollIntegrationTest {
 @Autowired StatutoryPayrollController automatic;@Autowired PayrollController payroll;@Autowired AccountRepository accounts;@Autowired StoreRepository stores;@Autowired StoreMemberRepository members;@Autowired WorkSessionRepository sessions;@Autowired PayrollEntryRepository entries;
 Account owner,staff;Store store;StoreMember member;WorkSession record;final String period="2026-10";
 @BeforeEach void setup(){String id=UUID.randomUUID().toString().substring(0,8);owner=accounts.save(new Account("auto-owner"+id,"unused",Role.OWNER,"사장","20000101"));staff=accounts.save(new Account("auto-staff"+id,"unused",Role.STAFF,"직원","20000101"));store=stores.save(new Store("급여 테스트","기타",null,null,null,"09:00","22:00",id,owner));members.save(new StoreMember(owner,store,Role.OWNER,MemberStatus.APPROVED));member=members.save(new StoreMember(staff,store,Role.STAFF,MemberStatus.APPROVED));record=new WorkSession(staff,store);ReflectionTestUtils.setField(record,"clockIn",LocalDateTime.of(2026,10,5,22,0));ReflectionTestUtils.setField(record,"clockOut",LocalDateTime.of(2026,10,6,0,0));record.assignWage(10000,"CONFIRMED",owner);sessions.saveAndFlush(record);}
 Settings valid(){return new Settings(true,false,true,false,1,List.of(new ConfirmedWork(record.getId(),true,List.of(),null)),List.of(new Week(LocalDate.of(2026,10,11),60,4,20,10000,true,true,true,true,null,3.0)),List.of(),true);}
 StatutoryPayrollController.View saved(){return automatic.save(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Save(0,valid()));}
 @Test void confirmedRulesRoundTripAndApplyExactlyOnce(){var v=saved();assertTrue(v.result().blockers().isEmpty());assertEquals(10000,v.records().getFirst().wage());v=automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash()));assertTrue(v.applied());automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash()));var s=payroll.get(owner,store.getId(),member.getId(),period);assertEquals(20000,s.basePay());assertEquals(40000,s.additions());assertEquals(60000,s.netPay());assertEquals(2,s.entries().size());assertEquals(60000,payroll.mine(staff,store.getId(),period).netPay());}
 @Test void changedAttendanceInvalidatesPreviewAndBlocksFinalization(){var v=saved();ReflectionTestUtils.setField(record,"clockOut",record.getClockOut().plusHours(1));assertThrows(ApiException.class,()->automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash())));}
 @Test void appliedAmountsMustBeRecalculatedAfterClockOutChanges(){var v=saved();automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash()));ReflectionTestUtils.setField(record,"clockOut",record.getClockOut().plusHours(1));assertThrows(ApiException.class,()->payroll.finalizePay(owner,store.getId(),member.getId(),period,new PayrollController.Finalize(true,true,true)));}
 @Test void recalculationReplacesOldEntriesWithCancellationAudit(){var v=saved();automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash()));ReflectionTestUtils.setField(record,"clockOut",record.getClockOut().plusHours(1));var changed=automatic.save(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Save(v.revision(),valid()));automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(changed.hash()));var all=entries.findByMemberAndPeriodOrderByIdAsc(member,period);assertEquals(4,all.size());assertEquals(2,all.stream().filter(PayrollEntry::isCancelled).count());assertEquals(45000,payroll.get(owner,store.getId(),member.getId(),period).additions());}
 @Test void missingBreakConfirmationCannotBeApplied(){var empty=new Settings(true,false,true,false,1,List.of(),valid().weeks(),List.of(),true);var v=automatic.save(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Save(0,empty));assertThrows(ApiException.class,()->automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash())));}
 @Test void manualAllowanceCannotBeDuplicatedByAutomaticCalculation(){payroll.add(owner,store.getId(),member.getId(),period,new PayrollController.Add("NIGHT","기존 야간",10000L,null,null,null,"manual-night-1"));var v=saved();assertThrows(ApiException.class,()->automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash())));}
 @Test void employeeCannotChangeSettingsAndRevisionProtectsConcurrentEdits(){assertThrows(ApiException.class,()->automatic.save(staff,store.getId(),member.getId(),period,new StatutoryPayrollController.Save(0,valid())));saved();assertThrows(ApiException.class,()->automatic.save(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Save(0,valid())));}
 @Test void automaticEntriesCannotBeCancelledIndividuallyOrSpoofed(){var v=saved();automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash()));var e=entries.findByMemberAndPeriodOrderByIdAsc(member,period).getFirst();assertThrows(ApiException.class,()->payroll.cancel(owner,store.getId(),member.getId(),e.getId(),period,new PayrollController.Cancel("개별 삭제")));assertThrows(ApiException.class,()->payroll.add(owner,store.getId(),member.getId(),period,new PayrollController.Add("OTHER","위조",1000L,null,null,null,"statutory-spoof")));}
 @Test void finalizedStatementsKeepTheirSnapshotAndRejectSettingsChanges(){var v=saved();automatic.apply(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Apply(v.hash()));var s=payroll.finalizePay(owner,store.getId(),member.getId(),period,new PayrollController.Finalize(true,true,true));assertTrue(s.finalized());assertThrows(ApiException.class,()->automatic.save(owner,store.getId(),member.getId(),period,new StatutoryPayrollController.Save(v.revision(),valid())));}
}
